// Define health checks for each provider
return [
  { id: 'youtube',    name: 'YouTube',    url: `https://www.googleapis.com/youtube/v3/videos?part=id&id=dQw4w9WgXcQ&key=${process.env.YOUTUBE_API_KEY}` },
  { id: 'dailymotion',name: 'DM',         url: 'https://api.dailymotion.com/video/x7tgd2g?fields=id,title' },
  { id: 'archive',    name: 'Archive.org', url: 'https://archive.org/advancedsearch.php?q=mediatype:movies&output=json&rows=1' },
  { id: 'tmdb',       name: 'TMDB',       url: `https://api.themoviedb.org/3/configuration?api_key=${process.env.TMDB_API_KEY}` }
].map(p => ({ json: p }));

const prev = $('Build Checks').item.json;
const result = $input.first().json;
const isError = !!result.error || result.httpCode >= 400;

return [{
  json: {
    id: prev.id,
    ok: !isError,
    quota_status: isError ? 'error' : 'ok',
    last_success_at: isError ? undefined : new Date().toISOString(),
    last_error_at:   isError ? new Date().toISOString() : undefined
  }
}];
